import kotlinx.coroutines.flow.Flow

/**
 * Repository contract for $Name$ (domain layer).
 *
 * Screens and use cases depend on this interface rather than on a concrete
 * implementation, so the data source can be swapped without UI changes.
 */
interface $Repository$ {
    /** Emits the full collection and re-emits whenever the cache changes. */
    fun get$Name$s(): Flow<$Name$>

    /** Returns a single item by id, or null when it does not exist. */
    suspend fun get$Name$ById(id: Long): $Name$?

    /** Inserts or replaces an item in the local cache. */
    suspend fun upsert$Name$($item$: $Name$)

    /** Removes an item from the local cache. */
    suspend fun delete$Name$(id: Long)
}

import kotlinx.coroutines.flow.Flow
import javax.inject.Inject
import javax.inject.Singleton

/**
 * Use case that observes the full collection.
 *
 * Use cases hold business logic and depend on a repository interface, which
 * keeps ViewModels lean. Call it directly: `getItemsUseCase()`.
 */
@Singleton
class Get$Name$sUseCase @Inject constructor(
    private val repository: $Repository$,
) {
    operator fun invoke(): Flow<$Name$> = repository.get$Name$s()
}

import androidx.room.ColumnInfo
import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Room entity persisting the $Name$ domain model to the $tableName$ table.
 *
 * Keep the entity aligned with the domain model and map between the two
 * with the mappers generated by the compRepositoryImpl template.
 *
 * ── Migration checklist (required whenever fields change) ─────────────
 *   1. Bump the @Database version (e.g. 1 → 2); keep exportSchema = true
 *      so Room writes schema JSON under app/schemas/.
 *   2. Add a Migration in the database module:
 *        val MIGRATION_1_2 = object : Migration(1, 2) {
 *            override fun migrate(db: SupportSQLiteDatabase) {
 *                db.execSQL("ALTER TABLE $tableName$ ADD COLUMN new_field TEXT")
 *            }
 *        }
 *   3. Register it: Room.databaseBuilder(...).addMigrations(MIGRATION_1_2).
 *   4. Never rename/delete an existing column in place: Room verifies the
 *      schema on launch and throws IllegalStateException on any mismatch.
 */
@Entity(tableName = "$tableName$")
data class $Entity$(
    // Auto-generated surrogate primary key.
    @PrimaryKey(autoGenerate = true)
    @ColumnInfo(name = "id")
    val id: Long = 0,

    @ColumnInfo(name = "$fieldOne$")
    val $FieldOne$: String = "",

    @ColumnInfo(name = "$fieldTwo$")
    val $FieldTwo$: String = "",
)

import androidx.room.Dao import androidx.room.Insert import androidx.room.OnConflictStrategy import androidx.room.Query import kotlinx.coroutines.flow.Flow
/** * ┌────────────────────────────────┐ * │ AppDatabase │ * │ (Room · owns the DAOs) │ * └───────────────┬────────────────┘ * │ exposes the DAO instance * ▼ * ┌────────────────────────────────┐ * │ $Dao$ (@Dao) │ ◄── this file * │ ── required types ─────────── │ * │ • $Entity$ : Room row │ * │ • Flow<...> : reactive reads │ * └───────────────┬────────────────┘ * │ observeAll() / getById() → Flow * ▼ * ┌────────────────────────────────┐ * │ $Repository$Impl (Hilt) │ * │ ── required types ─────────── │ * │ • $Dao$ : local cache │ * │ • $Api$ : Retrofit sync │ * └───────────────┬────────────────┘ * │ toDomain() / toEntity() * ▼ * ┌────────────────────────────────┐ * │ $Repository$ (domain) │ * │ consumed by ViewModel / UI │ * └────────────────────────────────┘ * * Remote ──▶ Dto ──▶ Entity ──▶ Room ──▶ Flow ──▶ Domain ──▶ UI * (network only seeds/caches; the UI reads Room reactively) * * Room DAO for the $Name$ domain model (stored in the $tableName$ table). * * Reads are exposed as [Flow] so the UI updates reactively whenever the * table changes. Writes use REPLACE conflict resolution. */ @Dao interface $Dao$ { /** Emits the item with the given id (or null) on every change. */ @Query("SELECT * FROM $tableName$ WHERE id = :id") fun getById(id: Long): Flow<$Entity$?>
/** Emits the full collection, ordered by id, on every change. */ @Query("SELECT * FROM $tableName$ ORDER BY id") fun observeAll(): Flow<List<$Entity$>>
/** Inserts or replaces a single item. */ @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(entity: $Entity$)
/** Inserts or replaces a batch of items (used by network sync). */ @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsertAll(entities: List<$Entity$>)
/** Deletes the item with the given id. */ @Query("DELETE FROM $tableName$ WHERE id = :id") suspend fun deleteById(id: Long) }

import com.google.gson.annotations.SerializedName

/**
 * DTO (data transfer object) matching the remote $Name$ payload.
 *
 * Field names map to the server JSON with [SerializedName]. Keep it separate
 * from the domain model because server shapes change more often.
 */
data class $Dto$(
    @SerializedName("id")
    val id: Long,

    @SerializedName("$fieldOne$")
    val $FieldOne$: String?,

    @SerializedName("$fieldTwo$")
    val $FieldTwo$: String?,
)

import retrofit2.http.Body
import retrofit2.http.DELETE
import retrofit2.http.GET
import retrofit2.http.POST
import retrofit2.http.Path

/**
 * Retrofit service definition for the $endpoint$ resource.
 *
 * All methods are suspend functions, so the repository implementation can
 * call them directly inside its coroutines.
 */
interface $Api$ {
    /** Fetches the full collection. */
    @GET("$endpoint$")
    suspend fun get$Name$s(): List<$Dto$>

    /** Fetches a single item by id. */
    @GET("$endpoint$/{id}")
    suspend fun get$Name$ById(@Path("id") id: Long): $Dto$

    /** Creates a new item server-side. */
    @POST("$endpoint$")
    suspend fun create$Name$(@Body body: $Dto$): $Dto$

    /** Deletes the item with the given id server-side. */
    @DELETE("$endpoint$/{id}")
    suspend fun delete$Name$(@Path("id") id: Long)
}

import javax.inject.Inject
import javax.inject.Singleton
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map

/**
 * Offline-first implementation of the repository contract.
 *
 * Room is the single source of truth: reads stream from the local cache and
 * the network is only contacted to seed or refresh it. Dependencies are
 * injected by Hilt, so this class is never instantiated by hand.
 */
@Singleton
class $Repository$Impl @Inject constructor(
    private val dao: $Dao$,
    private val api: $Api$,
) : $Repository$ {

    // Stream straight from Room; reads never hit the network.
    override fun get$Name$s(): Flow<$Name$> =
        dao.observeAll().map { entities -> entities.map { it.toDomain() } }

    override suspend fun get$Name$ById(id: Long): $Name$? {
        refreshIfEmpty()
        return dao.getById(id).first()?.toDomain()
    }

    // Writes go to Room first, then trigger a best-effort network sync.
    override suspend fun upsert$Name$($item$: $Name$) {
        dao.upsert($item$.toEntity())
        refreshFromRemote()
    }

    override suspend fun delete$Name$(id: Long) {
        dao.deleteById(id)
    }

    /** Pulls the remote collection and caches it locally. */
    private suspend fun refreshFromRemote() {
        runCatching { api.get$Name$s() }
            .onSuccess { dtos -> dao.upsertAll(dtos.map { it.toEntity() }) }
    }

    /** Seeds the cache once when it is empty (for example, first launch). */
    private suspend fun refreshIfEmpty() {
        if (dao.observeAll().first().isEmpty()) refreshFromRemote()
    }
}

/** Maps a remote DTO to a Room entity; nulls become empty strings. */
fun $Dto$.toEntity(): $Entity$ = $Entity$(
    id = id,
    $FieldOne$ = $FieldOne$.orEmpty(),
    $FieldTwo$ = $FieldTwo$.orEmpty(),
)

/** Maps a Room entity to the domain model. */
fun $Entity$.toDomain(): $Name$ = $Name$(
    id = id,
    $FieldOne$ = $FieldOne$,
    $FieldTwo$ = $FieldTwo$,
)

/** Maps a domain model to a Room entity (for local writes). */
fun $Name$.toEntity(): $Entity$ = $Entity$(
    id = id,
    $FieldOne$ = $FieldOne$,
    $FieldTwo$ = $FieldTwo$,
)

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.catch
import kotlinx.coroutines.flow.onStart
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

/**
 * ViewModel for the $Name$ screen, injected by Hilt.
 *
 * Exposes a single immutable [StateFlow] of the UI state; call [load] to
 * trigger a (re)load. Screens collect it with `collectAsStateWithLifecycle()`.
 */
@HiltViewModel
class $Name$ViewModel @Inject constructor(
    private val repository: $Repository$,
) : ViewModel() {

    // Backing flow is private; the screen only ever sees the exposed copy.
    private val _uiState = MutableStateFlow($UiState$())
    val uiState: StateFlow<$UiState$> = _uiState.asStateFlow()

    init {
        // Load immediately when the ViewModel is created.
        load()
    }

    /** Loads the collection, tracking loading/error state in the UiState. */
    fun load() {
        viewModelScope.launch {
            repository.get$Name$s()
                .onStart { _uiState.update { it.copy(isLoading = true) } }
                .catch { e -> _uiState.update { it.copy(isLoading = false, error = e.message) } }
                .collect { data -> _uiState.update { it.copy(isLoading = false, data = data) } }
        }
    }
}

/** Immutable UI state consumed by the screen. */
data class $UiState$(
    val isLoading: Boolean = false,
    val data: List<$Name$> = emptyList(),
    val error: String? = null,
)

import androidx.compose.runtime.Composable import androidx.compose.ui.Modifier import androidx.navigation.NavGraphBuilder import androidx.navigation.NavHostController import androidx.navigation.NavType import androidx.navigation.compose.NavHost import androidx.navigation.compose.composable import androidx.navigation.compose.rememberNavController import androidx.navigation.navArgument import org.koin.androidx.compose.viewModel
/** Central place for route strings, shared by the graph and navigation calls. */ object $Name$Routes { const val LIST = "$routeList$" const val DETAIL = "$routeDetail$/{id}"
/** Builds the detail route for a concrete id. */ fun detail(id: Long) = "$routeDetail$/$id" }
/** * Nestable graph builder: adds these destinations to any [NavHost]. * * Two ways to use it: * - Embed it inside another NavHost's builder lambda: * `NavHost(...) { $Name$Graph(navController) }` * - Or register it as a nested graph with its own start destination: * `navigation(startDestination = $Name$Routes.LIST, route = "$Name$Graph") { * $Name$Graph(navController) * }` * Each destination resolves its ViewModel through Koin with [viewModel], * which requires `koin-androidx-compose` and a started Koin app. * * Navigation architecture: * * ┌─────────────────────────────────────┐ * │ $Name$NavHost (@Composable) │ ← root host used by setContent * └───────────────────┬─────────────────┘ * │ rememberNavController() * ▼ * ┌─────────────────────────────────────┐ * │ NavHost (startDestination = LIST) │ * └───────────────────┬─────────────────┘ * │ route strings from $Name$Routes * ▼ * ┌─────────────────────────────────────┐ * │ LIST : "$routeList$" │ * │ $ListScreen$ ⇄ $ListViewModel$ (Koin) │ * │ │ navigate(detail(id)) │ * │ ▼ │ * │ DETAIL : "$routeDetail$/{id}" │ * │ $DetailScreen$ ⇄ $DetailViewModel$ (Koin) │ * └─────────────────────────────────────┘ * * One destination = one route → composable → ViewModel. Routes are * centralized in $Name$Routes so the graph and every navigation call * share a single source of truth. */ fun NavGraphBuilder.$Name$Graph( navController: NavHostController, ) { // List destination: the app entry point. composable(route = $Name$Routes.LIST) { val listViewModel: $ListViewModel$ by viewModel() $ListScreen$( onNavigateToDetail = { id -> navController.navigate($Name$Routes.detail(id)) }, ) } // Detail destination: receives its id as a typed navigation argument. composable( route = $Name$Routes.DETAIL, arguments = listOf(navArgument("id") { type = NavType.LongType }), ) { val detailViewModel: $DetailViewModel$ by viewModel() $DetailScreen$( onBack = { navController.popBackStack() }, ) } $END$ }
/** * Root host for standalone usage: `setContent { $Name$NavHost() }`. * * For nesting, skip this host and call `$Name$Graph(navController)` inside a * larger NavHost instead. */ @Composable fun $Name$NavHost( navController: NavHostController = rememberNavController(), modifier: Modifier = Modifier, ) { NavHost( navController = navController, startDestination = $Name$Routes.LIST, modifier = modifier, ) { $Name$Graph(navController) } }
